  R=[ex("Las dos vías de un tren que va en línea recta, ¿cómo son entre sí?", "Paralelas", "Siempre están a la misma distancia."),
     ex("Los dos bordes de una hoja que se juntan en una esquina, ¿cómo son entre sí?", "Perpendiculares", "Forman una esquina recta."),
     ex("Dos palitos de helado se cruzan en un punto formando una X, sin formar 90°. ¿Cómo se llaman esas rectas?", "Secantes", "Se intersectan en un punto.")],
  C=[ex("El borde de arriba y el borde de abajo de una puerta rectangular, ¿cómo son?", "Paralelos", "Son lados opuestos del rectángulo."),
     ex("El borde de arriba y un borde lateral de esa puerta, ¿cómo son?", "Perpendiculares", "Se juntan formando una esquina recta."),
     ex("Las manecillas de un reloj forman un cuarto de vuelta. ¿Cómo son entre sí?", "Perpendiculares", "Un cuarto de vuelta es un ángulo de 90°.")],
  A=[ex("¿A cuál de estas horas las manecillas son perpendiculares: 12:00, 6:00 o 9:00?", "9:00", "A las 12:00 están juntas y a las 6:00 forman una línea recta; a las 9:00 forman 90°."),
     ex("Una hoja rectangular, ¿cuántos pares de bordes paralelos tiene?", "2", "Los bordes opuestos forman dos pares."),
     ex("Una hoja rectangular, ¿cuántas esquinas rectas tiene?", "4", "Tiene cuatro esquinas de 90°.")],
  Z=[ex("Dos rectas dibujadas están a 3 cm de distancia al medirlas en varios lugares distintos. ¿Son paralelas?", "Sí", "La distancia entre ellas es siempre la misma."),
     ex("Dos rectas distintas del plano son perpendiculares a una tercera recta. ¿Cómo son entre sí?", "Paralelas", "Las dos forman 90° con la misma recta y nunca se cruzan.")],
